// Application service: transport-independent, bounded commands, device readback.
import {CMD,Reader,info,descriptor,trackDump,v14,encodeStep,decodeStep,integer} from './protocol.mjs';
import {P,TONE,copy} from './music.mjs';
export class Device{
 constructor(session,data){this.session=session;this.data=data;this.tracks=[];this.g=[];this.descs=[];this.gdescs=[];this.undo=null;}
 async rq(cmd,args=[]){return this.session.request(cmd,args);}
 async initialise(){this.info=info(await this.rq(CMD.INFO));if(!/^FELUCCA BE 1\.0-RC2$/.test(this.info.version)||this.info.pcount!==114||this.info.pe0!==106||this.info.ntrk!==4||this.info.nstep!==64)throw Error('This editor requires Bunker Evolved 1.0 (BE 1.0-RC2). No parameters were written.');const b=descriptor(await this.rq(CMD.DESC,[0,P.evolve]));if(b.label!=='EVOLVE')throw Error('Bunker parameter signature mismatch');const r=new Reader(await this.rq(CMD.DUMP));r.b();r.b();for(let i=0;i<this.info.pcount;i++)r.v();for(let i=0;i<this.info.gcount;i++)this.g.push(r.v());for(let i=0;i<this.info.gcount;i++)this.gdescs.push(descriptor(await this.rq(CMD.DESC,[1,i])));const original=(await this.status()).sel;for(let k=0;k<4;k++)await this.readTrack(k);await this.rq(CMD.TRACK,[original]);return this;}
 async status(){const r=new Reader(await this.rq(CMD.TRACK)),out={sel:r.b(),count:r.b(),armed:0};for(let i=0;i<out.count;i++){r.b();r.b();r.v();r.b();if(r.b())out.armed|=1<<i;}return out;}
 async readTrack(k){integer(k,0,3);await this.rq(CMD.TRACK,[k]);const t=trackDump(await this.rq(CMD.TRACK_DUMP,[k]),this.info.pcount);t.steps=[];for(let i=0;i<64;i++){const a=await this.rq(CMD.TRACK_STEP,[k,i]);t.steps.push(decodeStep(a.slice(2)));}const d=[];for(let i=0;i<this.info.pcount;i++)d.push(descriptor(await this.rq(CMD.DESC,[0,i])));if(d[P.scale].max===31)d[P.scale].names=this.data.scales.map(x=>x.name);this.descs[k]=d;this.tracks[k]=t;return t;}
 async readPhrase(k){const t=trackDump(await this.rq(CMD.TRACK_DUMP,[k]),this.info.pcount);t.steps=[];for(let i=0;i<64;i++)t.steps.push(decodeStep((await this.rq(CMD.TRACK_STEP,[k,i])).slice(2)));return t;}
 async set(k,id,value){integer(k,0,3);integer(id,0,this.info.pcount-1);const d=this.descs[k][id];integer(value,d.min,d.max);const r=new Reader(await this.rq(CMD.TRACK_PARAM,[k,id,...v14(value)]));r.b();r.b();const v=r.v();this.tracks[k].p[id]=v;if(v!==value&&!(d.fmt===8&&d.names[v-d.min]!==undefined&&d.names[v-d.min]===d.names[value-d.min]))throw Error(`${d.label} was not applied. Stop recording / song mode and read the device again.`);return v;}
 async global(id,value){const d=this.gdescs[id];integer(value,d.min,d.max);const r=new Reader(await this.rq(CMD.SET,[1,id,...v14(value)]));r.b();r.b();this.g[id]=r.v();if(this.g[id]!==value)throw Error('Global value was not applied');}
 async stop(){if((await this.status()).armed)throw Error('Turn off REC on all tracks first.');const a=await this.rq(CMD.SONG,[3]);if(a[1])throw Error('Could not stop the song');await new Promise(r=>setTimeout(r,35));}
 async preset(k,engine,preset){integer(engine,0,this.info.nengines-1);integer(preset,0,this.data.ENG[engine].presets.length-1);await this.stop();await this.rq(CMD.TRACK,[k]);const a=await this.rq(CMD.PRESET,[engine,preset]);if(a[0]!==engine||a[1]!==preset)throw Error('Preset was not applied');this.undo=null;await this.readTrack(k);}
 async sound(k,index){integer(index,0,15);const [,engine,preset,tone,attack,release,chorus,delay,reverb]=this.data.library.banks[k][index];await this.preset(k,engine,preset);const id=this.info.pe0+TONE[engine],d=this.descs[k][id];for(const [i,v] of [[id,d.min+Math.trunc(tone*(d.max-d.min)/127)],[P.attack,attack],[P.release,release],[P.chorus,chorus],[P.delay,delay],[P.reverb,reverb],[P.voice,k===2?1:0],[P.lrate,16],[P.lwave,0],[P.ltrigger,1],[P.lfilter,k===0?6:0],[P.spread,k===0?30:k===2?0:14]])await this.set(k,i,v);}
 signature(t){return JSON.stringify([t.engine,[P.root,P.scale,P.quant,P.evolve,P.length].map(id=>t.p[id]),t.steps.map(encodeStep)]);}
 async writePhrase(k,steps,params={}){if(!Array.isArray(steps)||steps.length!==64)throw Error('Expected 64 steps');steps.forEach(encodeStep);for(const [id,value] of Object.entries(params)){if(![P.root,P.scale,P.quant,P.evolve,P.length].includes(+id))throw Error('Not a phrase parameter');const d=this.descs[k][+id];integer(value,d.min,d.max);}await this.stop();const before=await this.readPhrase(k);this.undo={k,before,after:null};try{await this.set(k,P.evolve,0);for(const [id,v] of Object.entries(params))if(+id!==P.evolve)await this.set(k,+id,v);for(let i=0;i<64;i++){const expected=encodeStep(steps[i]),a=await this.rq(CMD.TRACK_STEP,[k,i,...expected]);if(JSON.stringify(a.slice(2))!==JSON.stringify(expected))throw Error(`Step ${i+1} did not match the device reply`);}if(params[P.evolve]!==undefined)await this.set(k,P.evolve,params[P.evolve]);const after=await this.readPhrase(k);if(JSON.stringify(after.steps.map(encodeStep))!==JSON.stringify(steps.map(encodeStep)))throw Error('Sequence verification failed');this.tracks[k]=after;this.undo.after=this.signature(after);return after;}catch(e){throw Error(`${e.message} The operation may be partial. Export the recovery phrase before reconnecting.`);}}
 async undoPhrase(){if(!this.undo?.after)throw Error('No verified edit to undo');const u=this.undo;await this.stop();const now=await this.readPhrase(u.k);if(this.signature(now)!==u.after)throw Error('The phrase changed since this edit. Undo was cancelled; export the recovery phrase if needed.');const params=Object.fromEntries([P.root,P.scale,P.quant,P.evolve,P.length].map(id=>[id,u.before.p[id]]));await this.writePhrase(u.k,u.before.steps,params);this.undo=null;}
}
